n-300 scale-x-0 group-hover:scale-x-100" style="background:#000000"></span></button></div><div class="relative"><button type="button" class="relative group inline-flex items-center gap-1.5" aria-haspopup="true" aria-expanded="false">Work<svg width="9" height="9" viewBox="0 0 12 12" class="transition-transform duration-200 "><path d="M2 4l4 4 4-4" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"></path></svg><span class="absolute -bottom-1 left-0 h-px w-full origin-left transition-transform duration-300 scale-x-0 group-hover:scale-x-100" style="background:#000000"></span></button></div><a href="{{ url('/contact') }}" class="relative group">Contact<span class="absolute -bottom-1 left-0 h-px w-full origin-left transition-transform duration-300 scale-x-0 group-hover:scale-x-100" style="background:#000000"></span></a></nav><div class="flex items-center gap-3"><a href="{{ url('/strategy-session') }}" class="lg-btn hidden sm:inline-flex rounded-full px-6 py-3 text-[13px] text-black tracking-wide hover:opacity-90 transition">Book A Strategy Session</a><button aria-label="Toggle menu" class="lg:hidden rounded-full border w-11 h-11 flex flex-col items-center justify-center gap-1" style="border-color:rgba(0,0,0,0.2)"><span class="h-[2px] w-5 transition-transform" style="background:#000000"></span><span class="h-[2px] w-5 transition-transform" style="background:#000000"></span></button></div></div></header><section class="relative overflow-hidden pt-6 sm:pt-10" style="background:linear-gradient(180deg, #ffffff 0%, #fafafa 70%, #E8F4FC 100%)"><div class="relative mx-auto max-w-[1400px] px-5 sm:px-8 lg:pl-28 pt-10 sm:pt-16 pb-14 sm:pb-20"><div class="mb-6 sm:mb-8"><span class="inline-flex items-center gap-2 text-[11px] tracking-[0.32em] uppercase font-medium" style="color:#000000;opacity:1;transform:none"><span class="h-px w-8 origin-left" style="background:#000000;transform:scaleX(1)"></span>Venture Building</span></div><div class="grid grid-cols-12 gap-6 sm:gap-10 items-start"><div class="col-span-12 lg:col-span-7"><h1 class="text-[clamp(34px,6vw,96px)] font-bold leading-[0.98] tracking-[-0.035em]" style="font-family:&#x27;Inter Tight&#x27;, sans-serif;color:#000000"><span class="block overflow-hidden"><span class="block" style="transform:none">You bring the capital.</span></span><span class="block overflow-hidden"><span class="block" style="transform:none">We build the <span style="font-family:&#x27;Fraunces&#x27;, serif" class="italic font-normal">venture.</span></span></span></h1><p class="mt-6 sm:mt-10 max-w-[640px] text-[16px] sm:text-[18px] md:text-[20px] leading-relaxed" style="color:#1a1a1a;opacity:1;transform:none">For investors, business owners, high-net-worth individuals and diasporans who want to launch a new venture without quitting their day job. We bring the scalable, profitable idea, the tech team to build it, the marketers to grow it, and the operators to run it. You fund the build — we run everything else. <strong>We don&#x27;t take equity. The company is 100% yours.</strong></p><div class="mt-7 sm:mt-10 flex flex-wrap items-center gap-3 sm:gap-4" style="opacity:1;transform:none"><a href="{{ url('/strategy-session') }}" style="display:inline-block"><span class="group relative inline-flex items-center gap-2 rounded-full px-7 py-4 text-[13px] tracking-wide overflow-hidden text-black" style="background:#4ECDC4;transform:none"><span class="relative z-10 inline-flex items-center gap-2">Start A Venture With Us<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="transition-transform duration-300 group-hover:translate-x-1"><path d="M5 12h14M13 5l7 7-7 7"></path></svg></span></span></a><a href="{{ url('/portfolio') }}" style="display:inline-block"><span class="group relative inline-flex items-center gap-2 rounded-full px-7 py-4 text-[13px] tracking-wide overflow-hidden border" style="border-color:#000000;color:#000000;transform:none"><span class="relative z-10 inline-flex items-center gap-2">See What We&#x27;ve Built<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="transition-transform duration-300 group-hover:translate-x-1"><path d="M5 12h14M13 5l7 7-7 7"></path></svg></span></span></a></div></div><div class="hidden lg:block col-span-5 relative h-[520px]"><div class="absolute inset-0 rounded-[28px] overflow-hidden shadow-[0_40px_80px_-30px_rgba(0,0,0,0.5)]" style="opacity:1;transform:none"><img src="{{ asset('assets/vb-hero-BKxo5rR_.webp') }}" alt="" class="w-full h-full object-cover" width="1280" height="1280"/></div><div class="absolute -bottom-6 -left-6 rounded-2xl bg-white px-5 py-4 shadow-[0_20px_50px_-15px_rgba(0,0,0,0.3)]" style="opacity:1;transform:none"><div class="text-[10px] tracking-[0.25em] uppercase" style="color:#6b6b6b">Ventures co-built</div><div class="mt-1 text-[28px] font-bold tabular-nums leading-none" style="color:#000000"><span>0</span></div></div><div class="absolute -top-4 -right-4 rounded-2xl bg-black text-white px-5 py-4 shadow-[0_20px_50px_-15px_rgba(0,0,0,0.4)]" style="opacity:1;transform:none"><div class="text-[10px] tracking-[0.25em] uppercase" style="color:#4ECDC4">Capital raised</div><div class="mt-1 text-[28px] font-bold tabular-nums leading-none">$<span>0<!-- -->M+</span></div></div></div></div></div></section><section class="bg-white py-20 sm:py-32 border-t" style="border-color:rgba(0,0,0,0.08)"><div class="mx-auto max-w-[1400px] px-5 sm:px-8"><div class="grid grid-cols-12 gap-6 sm:gap-10 items-end mb-10 sm:mb-16"><div class="col-span-12 lg:col-span-7"><span class="inline-flex items-center gap-2 text-[11px] tracking-[0.32em] uppercase font-medium" style="color:#000000;opacity:1;transform:none"><span class="h-px w-8 origin-left" style="background:#000000;transform:scaleX(1)"></span>The Model</span><h2 class="mt-5 sm:mt-6 text-[clamp(28px,4.5vw,68px)] font-bold leading-[1.02] tracking-[-0.03em]" style="color:#000000;font-family:&#x27;Inter Tight&#x27;, sans-serif">You fund it. We build, launch and <span style="font-family:&#x27;Fraunces&#x27;, serif" class="italic font-normal">run it.</span></h2></div><p class="col-span-12 lg:col-span-5 text-[15px] sm:text-[16px] leading-relaxed" style="color:#333">Most investors don&#x27;t have time to be founders. Most founders don&#x27;t have the team. LogicsGrid is the operating partner sitting between them — bringing the idea, the people and the playbook, while you keep full ownership of the company.</p></div><div class="grid grid-cols-12 gap-4 sm:gap-5"><div class="col-span-12 md:col-span-4 relative rounded-3xl border bg-white p-6 sm:p-9 overflow-hidden" style="border-color:rgba(0,0,0,0.12);opacity:1;transform:none"><div class="text-[12px] tracking-[0.3em] uppercase" style="color:#6b6b6b">01</div><h3 class="mt-6 sm:mt-10 text-[24px] sm:text-[28px] font-bold tracking-[-0.015em]" style="color:#000000;font-family:&#x27;Inter Tight&#x27;, sans-serif">The Idea</h3><p class="mt-3 sm:mt-4 text-[15px] leading-relaxed" style="color:#333">We bring you a vetted, highly scalable and profitable venture thesis — market sized, competition mapped, economics modelled. Or we pressure-test your own.</p><span class="pointer-events-none absolute inset-x-0 bottom-0 h-1 origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-500" class="lg-btn"></span></div><div class="col-span-12 md:col-span-4 relative rounded-3xl border bg-white p-6 sm:p-9 overflow-hidden" style="border-color:rgba(0,0,0,0.12);opacity:1;transform:none"><div class="text-[12px] tracking-[0.3em] uppercase" style="color:#6b6b6b">02</div><h3 class="mt-6 sm:mt-10 text-[24px] sm:text-[28px] font-bold tracking-[-0.015em]" style="color:#000000;font-family:&#x27;Inter Tight&#x27;, sans-serif">The Team</h3><p class="mt-3 sm:mt-4 text-[15px] leading-relaxed" style="color:#333">A full operating company in a box: senior product, engineering, design, marketing and operations talent — deployed to your venture from day one.</p><span class="pointer-events-none absolute inset-x-0 bottom-0 h-1 origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-500" class="lg-btn"></span></div><div class="col-span-12 md:col-span-4 relative rounded-3xl border bg-white p-6 sm:p-9 overflow-hidden" style="border-color:rgba(0,0,0,0.12);opacity:1;transform:none"><div class="text-[12px] tracking-[0.3em] uppercase" style="color:#6b6b6b">03</div><h3 class="mt-6 sm:mt-10 text-[24px] sm:text-[28px] font-bold tracking-[-0.015em]" style="color:#000000;font-family:&#x27;Inter Tight&#x27;, sans-serif">No Equity</h3><p class="mt-3 sm:mt-4 text-[15px] leading-relaxed" style="color:#333">We don&#x27;t take a single share. You fund product build, marketing and team salaries — we run the venture end-to-end. 100% of the upside stays with you.</p><span class="pointer-events-none absolute inset-x-0 bottom-0 h-1 origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-500" class="lg-btn"></span></div></div></div></section><section class="relative py-20 sm:py-32" style="background:#0a0a0a;color:#fff"><div class="mx-auto max-w-[1400px] px-5 sm:px-8"><div class="grid grid-cols-12 gap-6 sm:gap-10 mb-10 sm:mb-16"><div class="col-span-12 lg:col-span-6"><span class="inline-flex items-center gap-2 text-[11px] tracking-[0.32em] uppercase font-medium" style="color:#fff;opacity:1;transform:none"><span class="h-px w-8 origin-left" style="background:#fff;transform:scaleX(1)"></span>The Journey</span><h2 class="mt-5 sm:mt-6 text-[clamp(28px,4.5vw,68px)] font-bold leading-[1.02] tracking-[-0.03em]" style="font-family:&#x27;Inter Tight&#x27;, sans-serif">Five stages. One <span style="font-family:&#x27;Fraunces&#x27;, serif;color:#4ECDC4" class="italic font-normal">company.</span></h2></div><p class="col-span-12 lg:col-span-6 text-[15px] sm:text-[16px] leading-relaxed lg:self-end" style="color:#bcbcbc">Each stage has its own outcome and decision gate. You aren&#x27;t locked in past a stage that doesn&#x27;t earn its keep.</p></div><ol class="space-y-2"><li class="group grid grid-cols-12 gap-3 sm:gap-6 items-start lg:items-center border-t py-6 sm:py-8" style="border-color:rgba(255,255,255,0.12);opacity:1;transform:none"><div class="col-span-3 sm:col-span-2 lg:col-span-1 text-[11px] sm:text-[12px] tracking-[0.3em] uppercase" style="color:#4ECDC4">00</div><div class="col-span-9 sm:col-span-10 lg:col-span-3 text-[22px] sm:text-[24px] md:text-[30px] font-bold" style="font-family:&#x27;Inter Tight&#x27;, sans-serif">Thesis</div><p class="col-span-12 lg:col-span-5 text-[15px] leading-relaxed" style="color:#cfcfcf">We bring a vetted, scalable venture idea — or pressure-test yours — across market, competition and unit economics in a 2-week sprint. If it breaks here, you save 18 months.</p><div class="col-span-12 lg:col-span-3 text-[11px] sm:text-[12px] tracking-[0.22em] uppercase" style="color:#fff"><span class="opacity-60">Outcome — </span>Validated brief + go/no-go</div></li><li class="group grid grid-cols-12 gap-3 sm:gap-6 items-start lg:items-center border-t py-6 sm:py-8" style="border-color:rgba(255,255,255,0.12);opacity:1;transform:none"><div class="col-span-3 sm:col-span-2 lg:col-span-1 text-[11px] sm:text-[12px] tracking-[0.3em] uppercase" style="color:#4ECDC4">01</div><div class="col-span-9 sm:col-span-10 lg:col-span-3 text-[22px] sm:text-[24px] md:text-[30px] font-bold" style="font-family:&#x27;Inter Tight&#x27;, sans-serif">MVP</div><p class="col-span-12 lg:col-span-5 text-[15px] leading-relaxed" style="color:#cfcfcf">Our tech team designs, engineers and ships the product to real users in 8–12 weeks. Built on the stack that will scale — no throwaway prototypes. Funded by you, owned by you.</p><div class="col-span-12 lg:col-span-3 text-[11px] sm:text-[12px] tracking-[0.22em] uppercase" style="color:#fff"><span class="opacity-60">Outcome — </span>Live product + first 100 users</div></li><li class="group grid grid-cols-12 gap-3 sm:gap-6 items-start lg:items-center border-t py-6 sm:py-8" style="border-color:rgba(255,255,255,0.12);opacity:1;transform:none"><div class="col-span-3 sm:col-span-2 lg:col-span-1 text-[11px] sm:text-[12px] tracking-[0.3em] uppercase" style="color:#4ECDC4">02</div><div class="col-span-9 sm:col-span-10 lg:col-span-3 text-[22px] sm:text-[24px] md:text-[30px] font-bold" style="font-family:&#x27;Inter Tight&#x27;, sans-serif">Traction</div><p class="col-span-12 lg:col-span-5 text-[15px] leading-relaxed" style="color:#cfcfcf">Our marketing team runs growth experiments, paid loops, content, partnerships and sales — until we find the channels that compound. Operators take over day-to-day running of the business.</p><div class="col-span-12 lg:col-span-3 text-[11px] sm:text-[12px] tracking-[0.22em] uppercase" style="color:#fff"><span class="opacity-60">Outcome — </span>Repeatable acquisition channel</div></li><li class="group grid grid-cols-12 gap-3 sm:gap-6 items-start lg:items-center border-t py-6 sm:py-8" style="border-color:rgba(255,255,255,0.12);opacity:1;transform:none"><div class="col-span-3 sm:col-span-2 lg:col-span-1 text-[11px] sm:text-[12px] tracking-[0.3em] uppercase" style="color:#4ECDC4">03</div><div class="col-span-9 sm:col-span-10 lg:col-span-3 text-[22px] sm:text-[24px] md:text-[30px] font-bold" style="font-family:&#x27;Inter Tight&#x27;, sans-serif">Capital</div><p class="col-span-12 lg:col-span-5 text-[15px] leading-relaxed" style="color:#cfcfcf">When it&#x27;s time to raise, we prepare the investor materials, coach the founder through VC programs and accelerators, make warm intros from our network, and sit in the rooms during term-sheet negotiation.</p><div class="col-span-12 lg:col-span-3 text-[11px] sm:text-[12px] tracking-[0.22em] uppercase" style="color:#fff"><span class="opacity-60">Outcome — </span>Pre-seed or seed close</div></li><li class="group grid grid-cols-12 gap-3 sm:gap-6 items-start lg:items-center border-t py-6 sm:py-8" style="border-color:rgba(255,255,255,0.12);opacity:1;transform:none"><div class="col-span-3 sm:col-span-2 lg:col-span-1 text-[11px] sm:text-[12px] tracking-[0.3em] uppercase" style="color:#4ECDC4">04</div><div class="col-span-9 sm:col-span-10 lg:col-span-3 text-[22px] sm:text-[24px] md:text-[30px] font-bold" style="font-family:&#x27;Inter Tight&#x27;, sans-serif">Scale</div><p class="col-span-12 lg:col-span-5 text-[15px] leading-relaxed" style="color:#cfcfcf">We keep providing the team for ongoing growth — engineering, marketing and operations — as long as you want us. You stay in full control of the company; we stay accountable for execution.</p><div class="col-span-12 lg:col-span-3 text-[11px] sm:text-[12px] tracking-[0.22em] uppercase" style="color:#fff"><span class="opacity-60">Outcome — </span>Operating company, fully yours</div></li></ol></div></section><section class="bg-white py-20 sm:py-32 border-t" style="border-color:rgba(0,0,0,0.08)"><div class="mx-auto max-w-[1400px] px-5 sm:px-8 grid grid-cols-12 gap-8 sm:gap-12 items-start"><div class="col-span-12 lg:col-span-5"><span class="inline-flex items-center gap-2 text-[11px] tracking-[0.32em] uppercase font-medium" style="color:#000000;opacity:1;transform:none"><span class="h-px w-8 origin-left" style="background:#000000;transform:scaleX(1)"></span>What You Get</span><h2 class="mt-5 sm:mt-6 text-[clamp(26px,3.8vw,56px)] font-bold leading-[1.02] tracking-[-0.025em]" style="color:#000000;font-family:&#x27;Inter Tight&#x27;, sans-serif">A full operating company, <span style="font-family:&#x27;Fraunces&#x27;, serif" class="italic font-normal">without hiring one.</span></h2><p class="mt-5 sm:mt-6 text-[15px] sm:text-[16px] leading-relaxed max-w-[440px]" style="color:#333">You provide the funding for product build, marketing spend and team salaries. We provide everything else a venture needs in its first 18 months — and stay on for the growth phase if you want us to.</p></div><div class="col-span-12 lg:col-span-7"><ul